<section id="miembros" class="ios-card mt-5 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('users','h-5 w-5') ?></span><div><h2>Miembros y capacitación</h2><p>Registra principales, suplentes y horas reales de formación.</p></div></div><div class="mt-5 overflow-x-auto"><table class="data-table"><thead><tr><th>Nombre</th><th>Representación</th><th>Condición</th><th>Periodo</th><th>Capacitación</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td><strong><?= e($member['nombre']) ?></strong><span class="block text-[10px] text-slate-400"><?= e($member['documento']) ?></span></td><td><?= e($member['representacion']) ?></td><td><?= e($member['condicion']) ?></td><td><?= format_date($member['fecha_inicio']) ?> — <?= $member['fecha_fin']?format_date($member['fecha_fin']):'Actual' ?></td><td><?= number_format((float)$member['capacitacion_horas'],2,',','.') ?> h</td><td><span class="badge <?= $member['activo']?'badge-green':'badge-gray' ?>"><?= $member['activo']?'Activo':'Inactivo' ?></span></td><td><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/miembros/'.$member['id'].'/estado')) ?>"><?= csrf_field() ?><input type="hidden" name="activo" value="<?= $member['activo']?'0':'1' ?>"><button class="text-link" type="submit"><?= $member['activo']?'Retirar':'Reactivar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><details class="mt-4 rounded-2xl bg-slate-50 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Agregar miembro</summary><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/miembros')) ?>" class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><?= csrf_field() ?><div><label class="label">Persona del directorio</label><select name="empleado_id" class="input"><option value="0">Externa / manual</option><?php foreach($employees as $employee): ?><option value="<?= (int)$employee['id'] ?>"><?= e($employee['nombre']) ?> · <?= e($employee['documento']) ?></option><?php endforeach; ?></select></div><div><label class="label">Nombre manual</label><input name="nombre" class="input"></div><div><label class="label">Documento</label><input name="documento" class="input"></div><div><label class="label">Representación *</label><select name="representacion" class="input"><option>Trabajadores</option><option>Empleador</option></select></div><div><label class="label">Condición</label><select name="condicion" class="input"><option>Principal</option><option>Suplente</option></select></div><div><label class="label">Horas de capacitación</label><input type="number" step="any" min="0" name="capacitacion_horas" class="input" value="0"></div><div><label class="label">Fecha inicio *</label><input type="date" name="fecha_inicio" class="input" required></div><div><label class="label">Fecha fin</label><input type="date" name="fecha_fin" class="input"></div><div class="flex items-end justify-end"><button class="btn-secondary" type="submit">Agregar miembro</button></div></form></details></section>
<section id="reuniones" class="ios-card mt-5 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('calendar','h-5 w-5') ?></span><div><h2>Reuniones, asistencia y actas</h2><p>Programar una reunión no la marca como realizada.</p></div></div><details class="mt-4 rounded-2xl bg-slate-50 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Programar reunión</summary><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/reuniones')) ?>" class="mt-4 grid gap-4 sm:grid-cols-2"><?= csrf_field() ?><div><label class="label">Tipo</label><select name="tipo" class="input"><option>Ordinaria</option><option>Extraordinaria</option></select></div><div><label class="label">Fecha *</label><input type="date" name="fecha" class="input" required></div><div><label class="label">Lugar / medio *</label><input name="lugar" class="input" required></div><div><label class="label">Próxima reunión</label><input type="date" name="proxima_reunion" class="input"></div><div class="sm:col-span-2"><label class="label">Orden del día *</label><textarea name="orden_dia" class="input min-h-20" required></textarea></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Programar</button></div></form></details><div class="mt-5 space-y-4"><?php foreach($meetings as $meeting): $attendees=json_decode($meeting['asistentes_json'],true)?:[]; $attendeeIds=array_column($attendees,'id'); ?><article id="reunion-<?= (int)$meeting['id'] ?>" class="rounded-2xl ring-1 ring-slate-200"><div class="flex flex-wrap items-start justify-between gap-3 p-4"><div><span class="badge <?= status_class($meeting['estado']) ?>"><?= e($meeting['estado']) ?></span><span class="badge badge-slate"><?= e($meeting['tipo']) ?></span><h3 class="mt-2 text-sm font-semibold"><?= format_date($meeting['fecha']) ?> · <?= e($meeting['lugar']) ?></h3><p class="mt-1 whitespace-pre-line text-xs text-slate-500"><?= e($meeting['orden_dia']) ?></p></div><a href="<?= e(url('/evidencias?vinculo='.rawurlencode('comite_reunion:'.$meeting['id']).'#cargar')) ?>" class="btn-secondary"><?= icon('upload','h-4 w-4') ?> Acta y soportes</a></div><?php if($meeting['estado']==='Realizada'): ?><div class="border-t border-slate-100 bg-slate-50 p-4 text-xs"><p><strong>Asistencia:</strong> <?= count($attendees) ?> personas · <?= number_format((float)$meeting['quorum_porcentaje'],2,',','.') ?>% · <span class="<?= $meeting['quorum_cumple']?'text-emerald-600':'text-amber-600' ?>"><?= $meeting['quorum_cumple']?'Alcanza la regla configurada':'No alcanza la regla configurada' ?></span></p><p class="mt-2"><strong>Acta:</strong> <?= e($meeting['acta_referencia']) ?></p><p class="mt-2 whitespace-pre-line"><strong>Desarrollo:</strong> <?= e($meeting['desarrollo']) ?></p><?php if($meeting['compromisos']): ?><p class="mt-2 whitespace-pre-line"><strong>Compromisos:</strong> <?= e($meeting['compromisos']) ?></p><?php endif; ?></div><?php elseif($meeting['estado']==='Cancelada'): ?><p class="border-t border-slate-100 bg-slate-50 p-4 text-xs text-slate-500">Cancelación: <?= e($meeting['desarrollo']) ?></p><?php else: ?><details class="border-t border-slate-100 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Registrar resultado y asistencia</summary><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/reuniones/'.$meeting['id'])) ?>" class="mt-4"><?= csrf_field() ?><div class="grid gap-4 sm:grid-cols-2"><div><label class="label">Resultado</label><select name="estado" class="input"><option>Realizada</option><option>Cancelada</option></select></div><div><label class="label">Próxima reunión</label><input type="date" name="proxima_reunion" class="input" value="<?= e($meeting['proxima_reunion']) ?>"></div></div><fieldset class="mt-4 rounded-xl bg-slate-50 p-3"><legend class="px-1 text-xs font-semibold">Asistentes miembros activos</legend><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><?php foreach($members as $member): ?><?php if(!$member['activo'])continue; ?><label class="flex items-center gap-2 text-xs"><input type="checkbox" name="asistentes[]" value="<?= (int)$member['id'] ?>"><span><?= e($member['nombre']) ?><span class="block text-[9px] text-slate-400"><?= e($member['representacion'].' · '.$member['condicion']) ?></span></span></label><?php endforeach; ?></div></fieldset><label class="mt-3 flex items-start gap-2 text-xs text-slate-600"><input type="checkbox" name="confirmar_asistencia" value="1" class="mt-0.5" required><span>Confirmo que contrasté la asistencia con el acta real. El porcentaje se calcula sobre todos los miembros activos.</span></label><div class="mt-4 grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="label">Desarrollo / motivo de cancelación *</label><textarea name="desarrollo" class="input min-h-24"></textarea></div><div><label class="label">Compromisos</label><textarea name="compromisos" class="input min-h-20"></textarea></div><div><label class="label">Referencia real del acta *</label><input name="acta_referencia" class="input" placeholder="Código, folio o referencia del soporte"></div></div><div class="mt-4 flex justify-end"><button class="btn-primary" type="submit">Guardar resultado</button></div></form></details><?php endif; ?></article><?php endforeach; ?></div></section>
<section id="compromisos" class="ios-card mt-5 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('phva','h-5 w-5') ?></span><div><h2>Compromisos, recomendaciones y reportes</h2><p>Seguimiento individual con evidencia; el texto del acta se conserva como fuente original.</p></div></div><div class="mt-5 space-y-4"><?php if(!$commitments): ?><p class="rounded-xl bg-slate-50 p-4 text-xs text-slate-400">No hay compromisos individuales registrados.</p><?php endif; ?><?php foreach($commitments as $commitment): ?><article id="compromiso-<?= (int)$commitment['id'] ?>" class="rounded-2xl bg-slate-50 p-4 ring-1 ring-slate-100"><div class="flex flex-wrap items-start justify-between gap-3"><div><div class="flex flex-wrap gap-2"><span class="badge <?= status_class($commitment['estado']) ?>"><?= e($commitment['estado']) ?></span><span class="badge badge-slate"><?= e($commitment['categoria']) ?></span><?php if(!in_array($commitment['estado'],['Verificado','Cancelado'],true)&&$commitment['fecha_compromiso']<date('Y-m-d')): ?><span class="badge badge-red">Vencido</span><?php endif; ?></div><h3 class="mt-2 text-sm font-semibold"><?= e($commitment['descripcion']) ?></h3><p class="mt-1 text-xs text-slate-500"><?= e($commitment['responsable']) ?> · <?= format_date($commitment['fecha_compromiso']) ?><?= $commitment['reunion_fecha']?' · Reunión '.format_date($commitment['reunion_fecha']):'' ?></p></div><a href="<?= e(url('/evidencias?vinculo='.rawurlencode('comite_compromiso:'.$commitment['id']).'#cargar')) ?>" class="btn-secondary"><?= icon('upload','h-4 w-4') ?> Evidencias (<?= (int)$commitment['evidencias_revisadas'] ?> revisadas)</a></div><?php if($commitment['estado']!=='Verificado'): ?><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/compromisos/'.$commitment['id'].'/estado')) ?>" class="mt-4 grid items-end gap-3 sm:grid-cols-[180px_1fr_auto]"><?= csrf_field() ?><div><label class="label">Estado</label><select name="estado" class="input"><?php foreach(['Pendiente','En curso','Completado','Verificado','Cancelado'] as $status): ?><option<?= selected($commitment['estado'],$status) ?>><?= $status ?></option><?php endforeach; ?></select></div><div><label class="label">Resultado / justificación</label><input name="resultado" class="input" value="<?= e($commitment['resultado']) ?>"></div><button class="btn-secondary" type="submit">Actualizar</button></form><?php else: ?><p class="mt-3 text-xs text-emerald-700">Verificado por <?= e($commitment['verificado_por_nombre']??'usuario autorizado') ?> · <?= e($commitment['resultado']) ?></p><?php endif; ?></article><?php endforeach; ?></div><details class="mt-4 rounded-2xl border border-slate-200 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Registrar compromiso o recomendación</summary><form method="post" action="<?= e(url('/comites/'.$committee['id'].'/compromisos')) ?>" class="mt-4 grid gap-4 sm:grid-cols-2"><?= csrf_field() ?><div><label class="label">Categoría</label><select name="categoria" class="input"><option>Compromiso</option><option>Recomendacion Vigia</option><option>Reporte condicion insegura</option><option>Seguimiento COPASST</option></select></div><div><label class="label">Reunión relacionada</label><select name="reunion_id" class="input"><option value="0">Sin reunión específica</option><?php foreach($meetings as $meeting): ?><option value="<?= (int)$meeting['id'] ?>"><?= format_date($meeting['fecha']) ?> · <?= e($meeting['estado']) ?></option><?php endforeach; ?></select></div><div class="sm:col-span-2"><label class="label">Descripción *</label><textarea name="descripcion" class="input min-h-20" required></textarea></div><div><label class="label">Responsable *</label><input name="responsable" class="input" required></div><div><label class="label">Fecha compromiso *</label><input type="date" name="fecha_compromiso" class="input" required></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Registrar seguimiento</button></div></form></details></section>
